// SA V2 / SC Review V2 - helpers every package uses (SUBMIT, PREPARE, COMMIT, WORKER, client). Copied from smv2
// code/shared/lot_common.js (with f8's lotParseJ fix) and renamed sa / SA_. Included into a code node by the builders
// (v2build.include_js drops the "if (typeof module" line); every top-level name carries the sa / SA_ prefix so the file
// concatenates with a step's own helpers (s, q8, list, digits, parseJ) without a redeclaration.
const saS = (v) => (v === undefined || v === null ? "" : String(v)).trim();
// q8: the 8-dp rounding of COMPUTED quantities (STOCK_ADJUSTMENT code_node_O4tWJ5JH's q8); a NUMBER
const saQ8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
// a decimal as the 8-dp text the platform stores, never negative; a STRING
const saQtyStr = (v) => Math.max(0, saQ8(v)).toFixed(8);
const saDigits = (v) => /^[0-9]{1,20}$/.test(saS(v));
// a bigint id as a digit string: a digit string as is, a SAFE non-negative integer number as its digits; anything else
// (a 19-digit id that already went through a JS number, "", null, text) -> ""
const saIdStr = (v) => {
  if (typeof v === "number") return Number.isSafeInteger(v) && v >= 0 ? String(v) : "";
  const t = saS(v);
  return /^[0-9]{1,20}$/.test(t) ? t : "";
};
// JSON text with every bare 16+ digit integer TOKEN read as a STRING (snowflake ids survive); only whole integer tokens -
// never the fraction digits of a float such as 0.30000000000000004; null when it does not parse
const saParseJ = (t) => {
  if (t === undefined || t === null) return null;
  if (typeof t === "object") return t;
  try {
    return JSON.parse(String(t).replace(/"(?:[^"\\]|\\.)*"|(^\s*|[:\[,]\s*)(-?\d{16,})(?=\s*(?:[,\]}]|$))/g, (m, pre, num) => (num === undefined ? m : pre + '"' + num + '"')));
  } catch (e) {
    return null;
  }
};
const saList = (x) => (Array.isArray(x) ? x : x ? [x] : []).filter((r) => r !== undefined && r !== null);
// a JSON-text-or-array column (balance_index, reference_documents): the array, [] when empty / not a list
const saJsonList = (v) => {
  if (Array.isArray(v)) return v;
  const t = saS(v);
  if (!t) return [];
  const p = saParseJ(t);
  return Array.isArray(p) ? p : [];
};
// sql-node rows: JSON_OBJECT rows ({ j: "<json>" }) or already-plain objects -> plain objects (ids of 16+ digits as strings)
const saRows = (rows) => saList(rows).map((r) => (r && typeof r === "object" && typeof r.j === "string" ? saParseJ(r.j) : r)).filter((r) => r && typeof r === "object");
// STOCK_ADJUSTMENT code_node_GmKmvMGe: balance.category || "Unrestricted"
const saCategory = (c) => saS(c) || "Unrestricted";
// an entry's movement_type -> "ADD" (in) / "SUBTRACT" (out) / "" (invalid); readers are case-insensitive (prod holds
// In / IN / Out / OUT); the STORED casing is never rewritten (AutoCount V2 posting compares it exactly)
const saDirection = (mt) => {
  const t = saS(mt).toLowerCase();
  return t === "in" ? "ADD" : t === "out" ? "SUBTRACT" : "";
};
// UTF-8 byte length of a balance_index value (the column is TEXT, 65,535 bytes; prod's non-strict sql_mode truncates)
const saUtf8Bytes = (v) => {
  const t = Array.isArray(v) || (v && typeof v === "object") ? JSON.stringify(v) : saS(v);
  let n = 0;
  for (let i = 0; i < t.length; i++) {
    const c = t.charCodeAt(i);
    if (c < 0x80) n += 1;
    else if (c < 0x800) n += 2;
    else if (c >= 0xd800 && c <= 0xdbff) { n += 4; i++; }
    else n += 3;
  }
  return n;
};
const SA_LINE_MAX_BYTES = 60000;
const SA_MAX_ENTRIES = 5000;
const SA_CLASSIC_MAX_ENTRIES = 500;
const SA_REVIEW_LINE_MAX_ENTRIES = 50;
const saDbAddSeconds = function saDbAddSeconds(text, seconds) {
  const m = String(text || "").match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})/);
  if (!m) return "";
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]), Number(m[4]), Number(m[5]), Number(m[6])) + seconds * 1000);
  const p = (n) => (n < 10 ? "0" : "") + n;
  return d.getUTCFullYear() + "-" + p(d.getUTCMonth() + 1) + "-" + p(d.getUTCDate()) + " " + p(d.getUTCHours()) + ":" + p(d.getUTCMinutes()) + ":" + p(d.getUTCSeconds());
};
// the bounded statuses a COMPLETE_SA job may restore (CONTRACT.md §2): FORM -> Draft, REVIEW -> Cancelled; anything else =
// unknown = no unlock, REQUIRES_REVIEW SA_PREV_STATUS_UNKNOWN
const SA_PREV_STATUSES = ["Draft", "Cancelled"];
const saPrevStatusOk = (v) => SA_PREV_STATUSES.indexOf(saS(v)) >= 0;
// the payload part rows of one value: step_name <prefix><nnn>, 400,000 characters each (GR / Putaway / LOT V2's chunking)
const SA_CHUNK = 400000;
const saPartRows = function saPartRows(jobId, organizationId, prefix, value, status) {
  const text = JSON.stringify(value);
  const out = [];
  for (let at = 0, n = 1; at < text.length || n === 1; at += SA_CHUNK, n++) {
    out.push({ job_id: saS(jobId), organization_id: saS(organizationId), step_name: prefix + String(n).padStart(3, "0"), step_status: status || "PAYLOAD", attempt_count: 0,
      result_ref: text.slice(at, at + SA_CHUNK) });
  }
  return out;
};
// a part's chunk rows (step_name <prefix>nnn) joined in step-name order -> the value; null when there is no row, undefined
// when the joined text does not parse (GR's joinChunks)
const saJoinChunks = function saJoinChunks(rows, prefix) {
  const mine = saList(rows).filter((r) => saS(r.step_name).indexOf(prefix) === 0).sort((a, b) => (saS(a.step_name) < saS(b.step_name) ? -1 : 1));
  if (!mine.length) return null;
  const p = saParseJ(mine.map((r) => (r.result_ref === undefined || r.result_ref === null ? "" : String(r.result_ref))).join(""));
  return p === null ? undefined : p;
};
// SC guard (CONTRACT §11): reads only allData.id / .table_stock_count, saveAs and createAdjustment (mobile's pageStatus is an
// object); a Review that would build an SA (code_review_prep's own predicates) of > 500 lines with a variance is refused.
const scGuardIn = { allData: [{{workflowparams:allData}}][0], saveAs: [{{workflowparams:saveAs}}][0],
  createAdjustment: [{{workflowparams:createAdjustment}}][0], tenantId: [{{system:tenantId}}][0] };
let scGuardDoc = scGuardIn.allData;
if (typeof scGuardDoc === "string") scGuardDoc = saParseJ(scGuardDoc);
if (!scGuardDoc || typeof scGuardDoc !== "object" || Array.isArray(scGuardDoc)) scGuardDoc = {};
let scId = "0";
let tenantId = "0";
try {
  const t = saS(scGuardIn.tenantId);
  const id = saIdStr(scGuardDoc.id);
  if (saDigits(t) && saDigits(id)) {
    scId = id;
    tenantId = t;
  }
} catch (e) {
  scId = "0";
  tenantId = "0";
}
let reviewLines = 0;
let buildsSa = false;
let reason = "";
let message = "";
try {
  const lines = (Array.isArray(scGuardDoc.table_stock_count) ? scGuardDoc.table_stock_count : []).filter((item) => item && typeof item === "object" && item.line_status !== "Cancel");
  const allApproved = lines.every((item) => item.line_status === "Approved" || item.line_status === "Adjusted");
  const approvedItems = lines.filter((item) => item.review_status === "Approved" && item.line_status !== "Adjusted");
  const itemsWithVariance = approvedItems.filter((item) => item.variance_qty !== 0 && item.line_status === "Approved");
  buildsSa = approvedItems.length > 0 && (allApproved || scGuardIn.createAdjustment === "Yes");
  reviewLines = itemsWithVariance.length;
  const saveAs = scGuardIn.saveAs === undefined || scGuardIn.saveAs === null ? "" : String(scGuardIn.saveAs);
  if (saveAs === "Review" && buildsSa && reviewLines > SA_CLASSIC_MAX_ENTRIES) {
    reason = "SA_CLASSIC_TOO_BIG";
    message = "This review has " + reviewLines + " approved lines with a variance. Review at most " + SA_CLASSIC_MAX_ENTRIES + " lines at a time.";
  }
} catch (e) {
  reason = "";
  message = "";
}
return { scId: scId, tenantId: tenantId, reviewLines: String(reviewLines), buildsSa: buildsSa ? "YES" : "NO", reason: reason, message: message };

// A Processing SA made from this Stock Count refuses EVERY save of it (web and mobile alike).
const scGuardRows = [{{node:sql_node_SCguard.data}}][0];
const scGuardOut = [{{node:code_node_SCguard.data}}][0] || {};
let busy = false;
try {
  const rows = Array.isArray(scGuardRows) ? scGuardRows : scGuardRows && typeof scGuardRows === "object" ? [scGuardRows] : [];
  busy = rows.some((r) => r && typeof r === "object" && Number(r.busy_count) > 0);
} catch (e) {
  busy = false;
}
const reason = busy ? "SA_SC_BUSY" : String(scGuardOut.reason || "");
const message = busy ? "A Stock Adjustment from this Stock Count is being processed in the background - please wait for it to finish." : String(scGuardOut.message || "");
return { refuse: reason && message ? "YES" : "NO", reason: reason, message: message };

let entry = {{workflowparams:allData}};
entry.stock_count_status = "Draft";
const pageStatus = {{workflowparams:pageStatus}};
if (pageStatus === "Add") {
  if (entry.stock_count_no_type !== -9999 && (!entry.stock_count_no || entry.stock_count_no === null || entry.stock_count_no === "")) {
    entry.stock_count_no = "draft";
  }
}
entry.organization_id = {{workflowparams:organizationId}};
return { entry };

return {
  required_fields: JSON.stringify([
    { name: "plant_id", label: "Plant" },
    { name: "count_type", label: "Count Type" },
    { name: "stock_count_no", label: "Stock Count No" },
    { name: "table_stock_count", label: "Stock Count Items", isArray: true, arrayType: "object", arrayFields: [] }
  ]),
  data: JSON.stringify({
    plant_id: {{node:code_draft.data.entry.plant_id}},
    count_type: {{node:code_draft.data.entry.count_type}},
    stock_count_no: {{node:code_draft.data.entry.stock_count_no}},
    table_stock_count: {{node:code_draft.data.entry.table_stock_count}}
  })
};

let entry = {{workflowparams:allData}};
entry.table_stock_count = entry.table_stock_count || [];
entry.stock_count_status = "Issued";
entry.total_counted = `0 / ${entry.table_stock_count.length}`;
entry.total_variance = `0.00%`;
if (entry.stock_count_no_type !== -9999 && (!entry.stock_count_no || entry.stock_count_no === null || entry.stock_count_no === "" || entry.previous_status === "Draft")) {
  entry.stock_count_no = "issued";
}
entry.organization_id = {{workflowparams:organizationId}};
return { entry };

return {
  required_fields: JSON.stringify([
    { name: "plant_id", label: "Plant" },
    { name: "stock_count_no", label: "Stock Count No" },
    { name: "count_type", label: "Count Type" },
    { name: "table_stock_count", label: "Stock Count Items", isArray: true, arrayType: "object", arrayFields: [] }
  ]),
  data: JSON.stringify({
    plant_id: {{node:code_issued.data.entry.plant_id}},
    stock_count_no: {{node:code_issued.data.entry.stock_count_no}},
    count_type: {{node:code_issued.data.entry.count_type}},
    table_stock_count: {{node:code_issued.data.entry.table_stock_count}}
  })
};

let entry = {{workflowparams:allData}};
entry.table_stock_count = entry.table_stock_count || [];
const approvedItems = entry.approvedItems || [];
if (approvedItems.length > 0) {
  entry.table_stock_count = [...entry.table_stock_count, ...approvedItems];
}
const totalItems = entry.table_stock_count.length;
const lockedItems = entry.table_stock_count.filter((item) => item.is_counted === 1).length;
const total_counted = `${lockedItems} / ${totalItems}`;
const totalCountQty = entry.table_stock_count.reduce((sum, item) => sum + (parseFloat(item.count_qty) || 0), 0);
const totalSystemQty = entry.table_stock_count.reduce((sum, item) => sum + (parseFloat(item.system_qty) || 0), 0);
const totalVarianceQty = totalCountQty - totalSystemQty;
const variancePercentage = totalSystemQty > 0 ? Math.abs(totalVarianceQty / totalSystemQty) * 100 : 0;
entry.total_counted = total_counted;
entry.total_variance = `${variancePercentage.toFixed(2)}%`;
entry.review_status = (entry.review_status === "Recount" || !entry.review_status || entry.review_status === "") ? "To Be Reviewed" : entry.review_status;
entry.organization_id = {{workflowparams:organizationId}};
const hasUnlockedItems = entry.table_stock_count.some((item) => item.is_counted === 0 || !item.is_counted);
entry.stock_count_status = hasUnlockedItems ? "In Progress" : "Completed";
return { entry };

return {
  required_fields: JSON.stringify([
    { name: "plant_id", label: "Plant" },
    { name: "count_type", label: "Count Type" },
    { name: "table_stock_count", label: "Stock Count Items", isArray: true, arrayType: "object", arrayFields: [] }
  ]),
  data: JSON.stringify({
    plant_id: {{node:code_stockcount.data.entry.plant_id}},
    count_type: {{node:code_stockcount.data.entry.count_type}},
    table_stock_count: {{node:code_stockcount.data.entry.table_stock_count}}
  })
};

let entry = {{workflowparams:allData}};
const createAdjustment = {{workflowparams:createAdjustment}};
entry.table_stock_count = (entry.table_stock_count || []).filter((item) => item.line_status !== "Cancel");

const totalItems = entry.table_stock_count.length;
const lockedItems = entry.table_stock_count.filter((item) => item.is_counted === 1).length;
entry.total_counted = `${lockedItems} / ${totalItems}`;

const totalSystemQty = entry.table_stock_count.reduce((sum, item) => sum + (parseFloat(item.system_qty) || 0), 0);
const totalVarianceQty = entry.table_stock_count.reduce((sum, item) => {
  const varianceQty = parseFloat(item.variance_qty) || 0;
  const adjustedQty = parseFloat(item.adjusted_qty);
  const actualVariance = (!isNaN(adjustedQty) && adjustedQty !== null && adjustedQty !== varianceQty) ? adjustedQty : varianceQty;
  return sum + actualVariance;
}, 0);
const variancePercentage = totalSystemQty > 0 ? Math.abs(totalVarianceQty / totalSystemQty) * 100 : 0;
entry.total_variance = `${variancePercentage.toFixed(2)}%`;
entry.organization_id = {{workflowparams:organizationId}};

const hasRecountItems = entry.table_stock_count.some((item) => item.line_status === "Recount");
const allApproved = entry.table_stock_count.every((item) => item.line_status === "Approved" || item.line_status === "Adjusted");

if (hasRecountItems) {
  entry.review_status = "Recount";
  entry.stock_count_status = "In Progress";
} else if (allApproved) {
  entry.review_status = "Completed";
  entry.stock_count_status = "Completed";
} else {
  entry.review_status = "In Review";
}

const approvedItems = entry.table_stock_count.filter((item) => item.review_status === "Approved" && item.line_status !== "Adjusted");
const itemsWithVariance = approvedItems.filter((item) => item.variance_qty !== 0 && item.line_status === "Approved");

const doProcess = (approvedItems.length > 0 && (allApproved || createAdjustment === "Yes")) ? 1 : 0;
const hasApprovedVariance = (doProcess === 1 && itemsWithVariance.length > 0) ? 1 : 0;

let materialIds = [...new Set(itemsWithVariance.map((i) => i.material_id))];
let locationIds = [...new Set(itemsWithVariance.map((i) => i.location_id))];
let baseUomIds = [...new Set(itemsWithVariance.map((i) => i.base_uom_id))];
let batchIds = [...new Set(itemsWithVariance.filter((i) => i.batch_id).map((i) => i.batch_id))];
if (materialIds.length === 0) materialIds = ["0"];
if (locationIds.length === 0) locationIds = ["0"];
if (baseUomIds.length === 0) baseUomIds = ["0"];
if (batchIds.length === 0) batchIds = ["0"];

const isDigits = (v) => /^[0-9]+$/.test(String(v == null ? "" : v).trim());
const materialIdCsv = materialIds.filter(isDigits).join(",");
const orgIdSql = isDigits(entry.organization_id) ? String(entry.organization_id).trim() : "0";

return { entry, itemsWithVariance, doProcess, hasApprovedVariance, materialIds, locationIds, baseUomIds, batchIds, materialIdCsv, orgIdSql };

return {
  required_fields: JSON.stringify([
    { name: "plant_id", label: "Plant" },
    { name: "count_type", label: "Count Type" },
    { name: "table_stock_count", label: "Stock Count Items", isArray: true, arrayType: "object", arrayFields: [] }
  ]),
  data: JSON.stringify({
    plant_id: {{node:code_review_prep.data.entry.plant_id}},
    count_type: {{node:code_review_prep.data.entry.count_type}},
    table_stock_count: {{node:code_review_prep.data.entry.table_stock_count}}
  })
};

const itemsWithVariance = {{node:code_review_prep.data.itemsWithVariance}} || [];
const entry = {{node:code_review_prep.data.entry}};
const itemList = {{node:search_item.data.data}} || [];
const balanceList = {{node:search_item_balance.data.data}} || [];
const batchBalanceList = {{node:search_item_batch_balance.data.data}} || [];
const binList = {{node:search_bin_location.data.data}} || [];
const uomList = {{node:search_uom.data.data}} || [];
const batchList = {{node:search_batch.data.data}} || [];
const costRows = {{node:sql_review_costs.data}} || [];
let prefixRule = {{node:get_sa_prefix.data.data}};
if (Array.isArray(prefixRule)) prefixRule = prefixRule[0];

const organizationId = {{workflowparams:organizationId}};
const nickname = {{workflowparams:nickname}};
const adjustmentDate = {{workflowparams:adjustmentDate}};

const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
const isActive = (b) => b.is_deleted === 0 || b.is_deleted === "0" || !b.is_deleted;

// Found stock is valued at the plant's current cost so it does not drag WA/FIFO toward 0.
const costFor = (itemData, materialId, plantId, batchId) => {
  const method = itemData.material_costing_method;
  const src = method === "Weighted Average" ? "WA" : method === "First In First Out" ? "FIFO" : null;
  if (src) {
    const rows = costRows.filter(
      (r) => r.src === src && String(r.material_id) === String(materialId) && String(r.plant_id) === String(plantId)
    );
    const hit =
      rows.find((r) => Number(r.rn) === 1 && (batchId ? String(r.batch_id) === String(batchId) : !r.batch_id)) ||
      rows.find((r) => Number(r.rn_any) === 1);
    if (hit && q8(hit.cost) > 0) return q8(hit.cost);
  }
  return q8(itemData.purchase_unit_price);
};

const errors = [];
const groups = {};
const groupOrder = [];

for (const item of itemsWithVariance) {
  const itemData = itemList.find((it) => it.id === item.material_id) || {};
  const label = item.material_name || itemData.material_name || item.material_id;

  let varianceToUse = item.variance_qty;
  if (item.adjusted_qty !== undefined && item.adjusted_qty !== null && item.adjusted_qty !== item.variance_qty) {
    varianceToUse = item.adjusted_qty;
  }
  let varianceQtyInBaseUOM = varianceToUse;
  if (item.uom_id !== item.base_uom_id) {
    let tableUOMConversion = item.table_uom_conversion || itemData.table_uom_conversion;
    if (typeof tableUOMConversion === "string") {
      try { tableUOMConversion = JSON.parse(tableUOMConversion); } catch (e) { tableUOMConversion = null; }
    }
    if (tableUOMConversion && !Array.isArray(tableUOMConversion)) tableUOMConversion = [tableUOMConversion];
    if (tableUOMConversion && Array.isArray(tableUOMConversion)) {
      const currentUOMConversion = tableUOMConversion.find((conv) => conv.alt_uom_id === item.uom_id);
      if (currentUOMConversion && currentUOMConversion.base_qty) {
        varianceQtyInBaseUOM = varianceToUse * currentUOMConversion.base_qty;
      }
    }
  }

  const movementType = varianceQtyInBaseUOM > 0 ? "In" : "Out";
  const saQuantity = q8(Math.abs(varianceQtyInBaseUOM));
  if (saQuantity === 0) continue;

  const bin = binList.find((b) => b.id === item.location_id) || {};
  const locationName = bin.bin_location_combine || item.location_id;
  const binPlant = bin.plant_id || item.plant_id || entry.plant_id;

  if (Number(itemData.item_batch_management) === 1 && !item.batch_id) {
    errors.push(`${label} @ ${locationName}: batch is required for a batch-managed item`);
    continue;
  }

  const source = item.batch_id ? batchBalanceList : balanceList;
  const candidates = source.filter(
    (b) =>
      b.material_id === item.material_id &&
      b.location_id === item.location_id &&
      (!item.batch_id || b.batch_id === item.batch_id) &&
      isActive(b)
  );
  const balanceData =
    candidates.find((b) => b.plant_id === item.plant_id) || candidates.find((b) => b.plant_id === binPlant) || null;

  if (movementType === "Out") {
    const available = balanceData ? q8(balanceData.unrestricted_qty) : 0;
    if (available < saQuantity) {
      errors.push(
        balanceData
          ? `${label} @ ${locationName}: only ${available} unrestricted, cannot deduct ${saQuantity}`
          : `${label} @ ${locationName}: no stock balance, cannot deduct ${saQuantity}`
      );
      continue;
    }
  }

  const plantId = balanceData ? balanceData.plant_id : binPlant;
  const unitPrice = movementType === "In" ? costFor(itemData, item.material_id, plantId, item.batch_id) : 0;

  const balanceEntry = balanceData
    ? {
        balance_id: balanceData.id,
        material_id: balanceData.material_id,
        plant_id: balanceData.plant_id,
        location_id: balanceData.location_id,
        batch_id: balanceData.batch_id || null,
        balance_quantity: balanceData.balance_quantity,
        unrestricted_qty: balanceData.unrestricted_qty,
        block_qty: balanceData.block_qty,
        qualityinsp_qty: balanceData.qualityinsp_qty,
        reserved_qty: balanceData.reserved_qty,
        intransit_qty: balanceData.intransit_qty,
        organization_id: balanceData.organization_id,
        tenant_id: balanceData.tenant_id,
        create_user: balanceData.create_user,
        create_time: balanceData.create_time,
        create_dept: balanceData.create_dept,
        update_user: balanceData.update_user,
        update_time: balanceData.update_time,
        is_deleted: balanceData.is_deleted,
      }
    : {
        balance_id: null,
        material_id: item.material_id,
        plant_id: plantId,
        location_id: item.location_id,
        batch_id: item.batch_id || null,
        balance_quantity: 0,
        unrestricted_qty: 0,
        block_qty: 0,
        qualityinsp_qty: 0,
        reserved_qty: 0,
        intransit_qty: 0,
        organization_id: organizationId,
        is_deleted: 0,
      };
  balanceEntry.category = "Unrestricted";
  balanceEntry.movement_type = movementType;
  balanceEntry.sa_quantity = saQuantity;

  const key = `${item.material_id}|${plantId}|${movementType}|${movementType === "In" ? unitPrice : ""}`;
  if (!groups[key]) {
    groups[key] = { firstItem: item, itemData, plantId, unitPrice, balanceIndex: [], totalQuantity: 0, details: [] };
    groupOrder.push(key);
  }
  const group = groups[key];
  group.balanceIndex.push(balanceEntry);
  group.totalQuantity = q8(group.totalQuantity + saQuantity);

  const uomName = (uomList.find((u) => u.id === item.base_uom_id) || {}).uom_name || "";
  let batchName = "";
  if (item.batch_id) batchName = (batchList.find((bt) => bt.id === item.batch_id) || {}).batch_number || "";
  let detailLine = `${locationName}: ${saQuantity} ${uomName} (UNR) - ${movementType === "In" ? "IN" : "OUT"}`;
  if (batchName) detailLine += `\n[${batchName}]`;
  group.details.push(detailLine);
}

const stockAdjustmentTable = groupOrder.map((key) => {
  const group = groups[key];
  const firstItem = group.firstItem;
  const baseUomName = (uomList.find((u) => u.id === firstItem.base_uom_id) || {}).uom_name || "";
  return {
    material_id: firstItem.material_id,
    uom_id: firstItem.base_uom_id,
    material_name: group.itemData.material_name || "",
    item_category: firstItem.item_category,
    is_serialized_item: firstItem.is_serialized || 0,
    is_single_serial: firstItem.is_single || 0,
    total_quantity: group.totalQuantity,
    unit_price: group.unitPrice,
    balance_index: JSON.stringify(group.balanceIndex),
    adj_summary: `Total: ${group.totalQuantity} ${baseUomName}\nDETAILS:\n${group.details
      .map((detail, idx) => `${idx + 1}. ${detail}`)
      .join("\n")}`,
  };
});

const plantIds = [...new Set(groupOrder.map((key) => groups[key].plantId))];

const stockAdjustmentDoc = {
  stock_adjustment_status: "Draft",
  organization_id: organizationId,
  adjustment_no: "draft",
  adjustment_no_type: prefixRule && prefixRule.id ? prefixRule.id : null,
  stock_count_id: entry.id,
  adjustment_date: adjustmentDate,
  adjustment_type: "Stock Count",
  adjusted_by: nickname,
  plant_id: plantIds.length === 1 ? plantIds[0] : entry.plant_id,
  adjustment_remarks: entry.stock_count_remark || "",
  adjustment_remarks2: entry.stock_count_remark2 || "",
  adjustment_remarks3: entry.stock_count_remark3 || "",
  stock_adjustment: stockAdjustmentTable,
};

const shown = errors.slice(0, 10).join("; ");
const errorMessage = errors.length
  ? `Stock Adjustment not created. ${shown}${errors.length > 10 ? `; and ${errors.length - 10} more` : ""}`
  : "";

return {
  stockAdjustmentDoc,
  hasError: errors.length ? 1 : 0,
  errorMessage,
  hasLines: stockAdjustmentTable.length ? 1 : 0,
};

let entry = {{node:code_review_prep.data.entry}};
entry.table_stock_count = entry.table_stock_count.map((item) => {
  if (item.review_status === "Approved" && item.line_status !== "Adjusted") {
    return { ...item, line_status: "Adjusted" };
  }
  return item;
});
const allAdjusted = entry.table_stock_count.every((item) => item.line_status === "Adjusted");
entry.adjustment_status = allAdjusted ? "Fully Adjusted" : "Partially Adjusted";
return { entry };

